            return null;
        }
        const value = maybe_value.?;
        if (value.isUndefinedOrNull()) {
            return null;
        }
        const str = try value.toBunString(global);
        return allocations.track(str.toUTF8(arena_alloc));
}

pub inline fn getHmrRuntime(side: Side) HmrRuntime {
        return (if (Environment.codegen_embed) (switch (side) {
.client => .init(@embedFile("bake-codegen/bake.client.js")),
.server => .init(@embedFile("bake-codegen/bake.server.js")),
}) else .init((switch (side) {
.client => bun.runtimeEmbedFile(.codegen_eager, "bake.client.js"),
.server => bun.runtimeEmbedFile(.codegen, "bake.server.js"),
})));
}

pub fn addImportMetaDefines(allocator: std.mem.Allocator, define: *bun.options.Define, mode: Mode, side: Side) !void {
        const Define = bun.options.Define;
        _ = try define.insert(allocator, "import.meta.env.DEV", Define.Data.initBoolean((mode == .development)));
        _ = try define.insert(allocator, "import.meta.env.PROD", Define.Data.initBoolean((mode != .development)));
        _ = try define.insert(allocator, "import.meta.env.MODE", Define.Data.initStaticString((switch (mode) {
.development => (&.{ .data = "development" }),
.production_dynamic, .production_static => (&.{ .data = "production" }),
})));
        _ = try define.insert(allocator, "import.meta.env.SSR", Define.Data.initBoolean((side == .server)));
        _ = try define.insert(allocator, "import.meta.env.STATIC", Define.Data.initBoolean((mode == .production_static)));
}

pub fn printWarning() void {
        if ((bun.env_var.BUN_DEV_SERVER_TEST_RUNNER.get() == null)) {
            _ = bun.Output.warn("Be advised that Bun Bake is highly experimental, and its API\nwill have breaking changes. Join the <magenta>#bake<r> Discord\nchannel to help us find bugs: <blue>https://bun.com/discord<r>\n\n", .{});
            _ = bun.Output.flush();
        }
}
